<?php $title='Online Orders';$orderCan=static function($status){return OnlineOrder::can_action((int)$_SESSION['user']['id'],$status);};$h=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};ob_start(); ?>
<div class="d-flex align-items-center justify-content-between mb-3"><div><h3 class="mb-1">Online Orders</h3><p class="text-muted mb-0">Prepare, track, and collect payment for online pickup and flower delivery orders.</p></div><a class="btn btn-outline-primary" href="<?= url('?route=admin/online_orders') ?>">Refresh</a></div>
<form class="d-flex flex-wrap gap-2 mb-3" method="get" action="<?= url('') ?>"><input type="hidden" name="route" value="admin/online_orders"><label for="tracking-search" class="visually-hidden">Find tracking number</label><input id="tracking-search" name="tracking" class="form-control" style="max-width:320px" placeholder="Enter a tracking number" value="<?= $h($tracking) ?>"><button class="btn btn-outline-primary" type="submit">Find order</button></form>
<div class="alert alert-primary">Stock was already reserved at checkout; do not enter these orders again as new POS sales. <?php if($orderCan('paid')): ?>Record payment here to include an order in sales, then complete pickup or delivery when fulfilled.<?php else: ?>Your role permissions determine which preparation, payment and pickup actions are available.<?php endif; ?></div>
<?php if($selected): ?><div class="card"><div class="card-body"><div class="d-flex justify-content-between flex-wrap gap-2"><h4><?= $h($selected['tracking_number']) ?></h4><span class="badge bg-primary"><?= $h(ucfirst($selected['status'])) ?></span></div><p><?= $h($selected['customer_name']) ?> · <?= $h($selected['phone']) ?> · <?= $h($selected['branch_name']) ?></p><?php if (($selected['fulfillment_type'] ?? '') === 'delivery'): $delivery=json_decode($selected['delivery_details'] ?? '{}',true) ?: []; ?><div class="alert alert-light border"><strong>Flower delivery · <?= $h(strtoupper($selected['payment_choice'])) ?></strong><p class="mb-1"><?php require_once __DIR__.'/../../models/Psgc.php'; ?><?= $h(Psgc::formatted($delivery)) ?></p><p class="mb-1">Preferred date: <?= $h($delivery['delivery_date'] ?? '') ?> · Delivery fee: ₱<?= number_format((float)$selected['delivery_fee'],2) ?></p><?php if (!empty($delivery['gift_note'])): ?><p class="mb-0">Gift note: <?= $h($delivery['gift_note']) ?></p><?php endif; ?></div><?php endif; ?><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Quantity</th><th>Amount</th></tr></thead><tbody><?php foreach($selected['items'] as $item): ?><tr><td><?= $h($item['product_name']) ?></td><td><?= (int)$item['quantity'] ?></td><td>₱<?= number_format($item['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!empty($selected['financial'])):$of=$selected['financial']; ?><p class="small text-muted">Tax <?= !empty($of['tax_inclusive'])?'(included)':'' ?>: PHP <?= number_format($of['tax_cents']/100,2) ?> · Service charge: PHP <?= number_format($of['service_cents']/100,2) ?></p><?php endif; ?><p class="fw-bold">Total: ₱<?= number_format($selected['total'],2) ?> · Payment: <?= $h($selected['payment_status']) ?></p>
<form method="post" action="<?= url('?route=admin/online_orders') ?>" class="d-flex flex-wrap gap-2 align-items-center"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="order_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="tracking" value="<?= $h($selected['tracking_number']) ?>"><?php if($selected['status']==='pending'): ?><?php if($orderCan('preparing')): ?><button class="btn btn-primary" name="status" value="preparing">Start preparing</button><?php endif; ?><?php if($selected['payment_status']==='unpaid' && $orderCan('cancelled')): ?><button class="btn btn-outline-danger" name="status" value="cancelled">Cancel and release stock</button><?php endif; ?><?php elseif($selected['status']==='preparing' && $orderCan('ready')): ?><button class="btn btn-primary" name="status" value="ready">Mark ready for pickup</button><?php elseif($selected['status']==='ready' && $selected['payment_status']==='paid' && $orderCan('completed')): ?><button class="btn btn-primary" name="status" value="completed">Complete <?= ($selected['fulfillment_type'] ?? '')==='delivery'?'delivery':'pickup' ?></button><?php endif; ?>
<?php if($selected['payment_status']==='unpaid' && in_array($selected['status'],['pending','preparing','ready'],true) && $orderCan('paid')): ?><label for="payment-method">Payment received by</label><select id="payment-method" class="form-select w-auto" name="payment_method"><?php foreach(CheckoutPolicy::methods() as $method): ?><option><?= $method ?></option><?php endforeach; ?></select><button class="btn btn-success" name="status" value="paid">Mark paid</button><?php endif; ?></form><div class="mt-4"><h5>Progress</h5><?php foreach($selected['events'] as $event): ?><p class="small mb-1"><?= $h($event['created_at']) ?> · <?= $h($event['note']) ?></p><?php endforeach; ?></div></div></div><?php endif; ?>
<style>.order-board{display:grid;grid-template-columns:repeat(4,minmax(240px,1fr));gap:14px;overflow-x:auto;padding:2px 2px 16px}.order-lane{background:#f3f6fb;border:1px solid #e4eaf3;border-radius:16px;padding:14px;min-height:220px}.order-lane h5{font-size:15px;display:flex;justify-content:space-between}.order-tile{display:block;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin-top:12px;color:inherit;text-decoration:none;box-shadow:0 3px 10px #24334c08;transition:transform .15s,border-color .15s}.order-tile:hover{transform:translateY(-2px);border-color:#5d87ff}.order-tile small{display:block;color:#66758b;overflow-wrap:anywhere}.order-tile strong{display:block;margin:6px 0}.order-lane:nth-child(2){border-top:4px solid #ffae1f}.order-lane:nth-child(3){border-top:4px solid #13deb9}.order-lane:first-child{border-top:4px solid #5d87ff}</style>
<div class="order-board" aria-label="Online order board">
<?php foreach(['pending'=>'New orders','preparing'=>'Preparing','ready'=>'Ready','completed'=>'Completed'] as $state=>$label): $lane=array_filter($orders,static function($o)use($state){return $o['status']===$state;}); ?>
<section class="order-lane"><h5><?= $h($label) ?><span class="badge bg-primary"><?= count($lane) ?></span></h5><?php foreach($lane as $o): ?><a class="order-tile" href="<?= url('?route=admin/online_orders&tracking='.rawurlencode($o['tracking_number'])) ?>"><small><?= $h($o['tracking_number']) ?></small><strong><?= $h($o['customer_name']) ?></strong><small><?= $h($o['branch_name']) ?> · <?= $h($o['created_at']) ?></small><div class="d-flex justify-content-between mt-3"><b>₱<?= number_format($o['total'],2) ?></b><span class="badge <?= $o['payment_status']==='paid'?'bg-success':'bg-warning text-dark' ?>"><?= $h(ucfirst($o['payment_status'])) ?></span></div></a><?php endforeach; ?><?php if(!$lane): ?><p class="small text-muted mt-3">No orders here.</p><?php endif; ?></section><?php endforeach; ?></div>
<details class="card p-3 mt-3"><summary>Cancelled and refunded orders</summary><?php foreach($orders as $o): if(!in_array($o['status'],['cancelled','refunded'],true))continue; ?><a class="order-tile" href="<?= url('?route=admin/online_orders&tracking='.rawurlencode($o['tracking_number'])) ?>"><?= $h($o['tracking_number']) ?> · <?= $h($o['customer_name']) ?> · <?= $h(ucfirst($o['status'])) ?></a><?php endforeach; ?></details>
<?php $content=ob_get_clean();require __DIR__.'/../layouts/admin.php'; ?>
